package br.com.andre22bodybuilder.blackpharma; import android.app.*;import android.os.*;import android.webkit.*;import android.graphics.Color; public class MainActivity extends Activity{WebView w;@Override public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);w.setBackgroundColor(Color.rgb(6,6,5));WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);w.setWebViewClient(new WebViewClient());setContentView(w);if(Build.VERSION.SDK_INT>=21){w.setPadding(0,getStatusBarHeight(),0,0);w.setClipToPadding(false);}w.loadUrl("file:///android_asset/index.html");}private int getStatusBarHeight(){int id=getResources().getIdentifier("status_bar_height","dimen","android");return id>0?getResources().getDimensionPixelSize(id):0;}@Override public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();}}